mod solution;

fn main() {
    let cases = [
    (r#"n=5 edges=(0,2),(1,2),(2,4)"#, r#"0,1,4"#),
    (r#"n=3 edges=(0,1),(1,2)"#, r#"1"#),
    (r#"
n=3 edges=(0,1),(1,2)
"#, r#"1"#),
    (r#"  
n=5 edges=(0,2),(1,2),(2,4)
  "#, r#"0,1,4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS adjacency-list");
}
